{
    ChangeState(-1);
    switch (m_state) {
    case 6: ++stats->m_count3; return;
    case 3: ++stats->m_count0; return;
    case 5: ++stats->m_count4; return;
    case 4: ++stats->m_count2; return;
    case 2: ++stats->m_count1; return;
    }
}

